      SUBROUTINE ENRIC3CC     CALCULATES CONTRIBUTION FROM THIRD-ORDER TERMSC     TO FIRST- AND SECOND-ORDER MATRICES FROM SHIFTEDC     REFERENCE TRAJECTORYCC     LIST OF COMMON BLOCKSC      INCLUDE 'COACOM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RA.CIN'      INCLUDE 'TA.CIN'      INCLUDE 'UA.CIN'CC-----------------------------------------------------------------C     CONTRIBUTION OF THIRD-ORDER TERMS TO FIRST-ORDER MATRIXC      DO 20 J = 1, 4      IND = 0      DO 20 L3 = 1, 6      DO 20 L2 = 1, L3      DO 20 L1 = 1, L2      IND = IND + 1      RA(J,L1) = RA(J,L1) + UA(J,IND)*COA(L2)*COA(L3)      RA(J,L2) = RA(J,L2) + UA(J,IND)*COA(L1)*COA(L3)      RA(J,L3) = RA(J,L3) + UA(J,IND)*COA(L1)*COA(L2)   20 CONTINUECC     CONTRIBUTION OF THIRD-ORDER TERMS TO SECOND-ORDER MATRIXC      IF (NORD2 .LT. 2) GO TO 100      DO 50 J = 1, 4      IND = 0      IND23 = 0      IND13 = 0      DO 50 L3 = 1, 6      IND12 = 0      IND13S = IND13            DO 50 L2 = 1, L3      IND13 = IND13S      IND23 = IND23 + 1      DO 50 L1 = 1, L2      IND12 = IND12 + 1      IND13 = IND13 + 1      IND = IND + 1      TA(J,IND23) = TA(J,IND23) + UA(J,IND)*COA(L1)      TA(J,IND13) = TA(J,IND13) + UA(J,IND)*COA(L2)      TA(J,IND12) = TA(J,IND12) + UA(J,IND)*COA(L3)   50 CONTINUEC  100 RETURN      END